class Stack:
    def __init__(self):
        self.items = []

    def push(self, item):
        """Add an item to the top of the stack."""
        self.items.append(item)

    def pop(self):
        """Remove and return the top item of the stack. If the stack is empty, return None."""
        if self.isEmpty():
            return None
        return self.items.pop()

    def peek(self):
        """Return the top item of the stack without removing it. If the stack is empty, return None."""
        if self.isEmpty():
            return None
        return self.items[-1]

    def isEmpty(self):
        """Check if the stack is empty."""
        return len(self.items) == 0

