class MinStack:
    def __init__(self):
        # The main stack to store all the elements
        self.stack = []
        # The auxiliary stack to store the minimum elements
        self.min_stack = []

    def push(self, x):
        """Push element x onto stack."""
        self.stack.append(x)
        # Push x to min_stack if it's empty or x is less than or equal to the current minimum
        if not self.min_stack or x <= self.min_stack[-1]:
            self.min_stack.append(x)

    def pop(self):
        """Removes the element on top of the stack."""
        if self.stack:
            top = self.stack.pop()
            # If the popped element is the current minimum, also pop it from min_stack
            if top == self.min_stack[-1]:
                self.min_stack.pop()
            return top

    def peek(self):
        """Get the top element."""
        if self.stack:
            return self.stack[-1]

    def is_empty(self):
        """Check if the stack is empty."""
        return len(self.stack) == 0

    def get_min(self):
        """Retrieve the minimum element in the stack."""
        if self.min_stack:
            return self.min_stack[-1]
