class MinHeap:
    def __init__(self):
        """Initialize an empty min-heap."""
        self.heap = []

    def heapify(self, index):
        """Maintain the heap property starting from the given index."""
        smallest = index
        left_child = 2 * index + 1
        right_child = 2 * index + 2

        if left_child < self.size() and self.heap[left_child] < self.heap[smallest]:
            smallest = left_child

        if right_child < self.size() and self.heap[right_child] < self.heap[smallest]:
            smallest = right_child

        if smallest != index:
            self.heap[index], self.heap[smallest] = self.heap[smallest], self.heap[index]
            self.heapify(smallest)

    def insert(self, element):
        """Insert a new element into the heap."""
        self.heap.append(element)
        current = self.size() - 1
        while current > 0 and self.heap[(current - 1) // 2] > self.heap[current]:
            parent = (current - 1) // 2
            self.heap[current], self.heap[parent] = self.heap[parent], self.heap[current]
            current = parent

    def extract_min(self):
        """Remove and return the smallest element from the heap. Return None if the heap is empty."""
        if self.is_empty():
            return None
        elif self.size() == 1:
            return self.heap.pop()

        min_element = self.heap[0]
        self.heap[0] = self.heap.pop()
        self.heapify(0)
        return min_element

    def get_min(self):
        """Return the smallest element in the heap without removing it. Return None if the heap is empty."""
        if self.is_empty():
            return None
        return self.heap[0]

    def is_empty(self):
        """Return True if the heap is empty, otherwise False."""
        return len(self.heap) == 0

    def size(self):
        """Return the number of elements in the heap."""
        return len(self.heap)
