class Graph:
    def __init__(self):
        # Initialize an empty dictionary to store the graph.
        # Keys are the vertices and values are the adjacent vertices (in a list).
        self.graph = {}

    def add_vertex(self, vertex):
        """Adds a vertex to the graph if it doesn't already exist."""
        if vertex not in self.graph:
            self.graph[vertex] = []

    def add_edge(self, vertex1, vertex2):
        """Adds an undirected edge between vertex1 and vertex2. Also adds the vertices if they do not exist."""
        if vertex1 not in self.graph:
            self.add_vertex(vertex1)
        if vertex2 not in self.graph:
            self.add_vertex(vertex2)
        self.graph[vertex1].append(vertex2)
        self.graph[vertex2].append(vertex1)

    def contains_cycle(self):
        """Checks if there's a cycle in the graph using a DFS traversal."""
        visited = set()

        def dfs(vertex, parent):
            visited.add(vertex)
            for neighbor in self.graph[vertex]:
                if neighbor not in visited:
                    if dfs(neighbor, vertex):
                        return True
                elif neighbor != parent:
                    return True
            return False

        for vertex in self.graph:
            if vertex not in visited:
                if dfs(vertex, None):
                    return True
        return False

