from typing import Union, List

def parse_input(s: str) -> List[Union[int, float, bool, str]]:
    """
    Parses each line of the input string and returns a list of values with the appropriate data type.

    :param s: A multi-line string where each line contains a single value.
    :return: A list of values with the appropriate data type (int, float, bool, or str).
    """
    def parse_line(line: str) -> Union[int, float, bool, str]:
        line = line.strip()
        if line.lower() == "true":
            return True
        elif line.lower() == "false":
            return False
        try:
            return int(line)
        except ValueError:
            try:
                return float(line)
            except ValueError:
                return line

    return [parse_line(line) for line in s.splitlines()]
