def simplify_exam_result(record):
    """
    Simplifies the exam result category for a given student record.

    Parameters:
    record (dict): A dictionary containing the student's name and exam result.

    Returns:
    dict: A new dictionary with the student's name and simplified exam result category.
    """
    original_result = record['exam_result']

    if original_result in ('PASS', 'GRADUATED'):
        return {'name': record['name'], 'simplified_result': 'SUCCESS'}
    elif original_result in ('FAIL', 'DISMISSED', 'EXPELLED'):
        return {'name': record['name'], 'simplified_result': 'FAILURE'}
    elif original_result in ('INCOMPLETE', 'DROPPED', 'AUDIT'):
        return {'name': record['name'], 'simplified_result': 'INCOMPLETE'}
    elif original_result in ('WITHDRAWN', 'READMITTED'):
        return {'name': record['name'], 'simplified_result': 'WITHDRAWN'}
    elif original_result == 'TRANSFERRED':
        return {'name': record['name'], 'simplified_result': 'TRANSFERRED'}
    elif original_result in ('SUSPENDED', 'DECEASED'):
        return {'name': record['name'], 'simplified_result': 'DISCIPLINARY'}
    else:
        return {'name': record['name'], 'simplified_result': 'UNKNOWN'}
