def address_dict_by_email(users):
    """
    Recursively constructs a dictionary mapping email addresses to user address information.

    :param users: List of dictionaries, each representing a user with 'id', 'name', 'email', and 'address' keys.
    :return: Dictionary with email addresses as keys and corresponding address information as values.
    :raises Exception: If an error occurs during processing.
    """
    def build_dict(index):
        if index >= len(users):
            return {}
        try:
            user = users[index]
            email = user.get('email')
            if email:
                address = user.get('address')
                if address and all(key in address for key in ['street', 'city', 'state', 'zip']):
                    return {email: address, **build_dict(index + 1)}
            return build_dict(index + 1)
        except Exception:
            raise Exception("Error processing the data into a dictionary.")

    return build_dict(0)
