def binary_search_optimized(L, e):
    """
    Determines if the target integer e is present in the sorted list L using binary search.

    Parameters:
    L (list of int): A sorted list of integers.
    e (int): The target integer to search for in L.

    Returns:
    bool: True if e is found in L, False otherwise.
    """
    def binary_search_helper(low, high):
        if low > high:
            return False
        mid = (low + high) // 2
        if L[mid] == e:
            return True
        elif L[mid] < e:
            return binary_search_helper(mid + 1, high)
        else:
            return binary_search_helper(low, mid - 1)

    return binary_search_helper(0, len(L) - 1)
